import sys
import binascii

# Load 64KB blocks from each image
def load_blocks(fname):
    blocks = []
    with open(fname, 'rb') as f:
        for _ in range(128):
            data = f.read(512)
            blocks.append(data)
    return blocks

def check_inverted(b1, b2):
    # If b1 XOR b2 is all 0xFF, then they're inverses.
    return all((x ^ y) == 0xFF for x, y in zip(b1, b2))

def block_xor(b1, b2):
    return bytes([x ^ y for x, y in zip(b1, b2)])

def print_block_stats(blocks0, blocks1):
    for i, (b0, b1) in enumerate(zip(blocks0, blocks1)):
        xor = block_xor(b0, b1)
        same = b0 == b1
        inv = check_inverted(b0, b1)
        xor_ff = all(x == 0xFF for x in xor)
        # Print patterns to help find parity/inversion
        print(f"Block {i:03}: same={same}, inverted={inv}, xor_ff={xor_ff}, xor0={xor[0]:02x} ...")
        # Optionally: print(binascii.hexlify(b0[:16]), binascii.hexlify(b1[:16]))

if __name__ == '__main__':
    b0 = load_blocks('disk0_64k.bin')
    b1 = load_blocks('disk1_64k.bin')
    print_block_stats(b0, b1)

import sys

BLOCK_SIZE = 512
BLOCKS = 128

def read_blocks(fname):
    with open(fname, 'rb') as f:
        return [f.read(BLOCK_SIZE) for _ in range(BLOCKS)]

def xor_bytes(a, b):
    return bytes([x ^ y for x, y in zip(a, b)])

def is_inverted(a, b):
    # Inverted if a XOR b == 0xFF for all bytes
    return all((x ^ y) == 0xFF for x, y in zip(a, b))

def main():
    b0 = read_blocks('img0.64k')
    b1 = read_blocks('img1.64k')

    for i in range(BLOCKS):
        x = xor_bytes(b0[i], b1[i])
        zero = all(v == 0 for v in x)
        ff = all(v == 0xFF for v in x)
        inv = is_inverted(b0[i], b1[i])
        print(f'Block {i:03}: XOR=0x{sum(x):x} zero={zero} ff={ff} inverted={inv}')

if __name__ == '__main__':
    main()

# Hypothesis: Interleave blocks in checkerboard pattern for the first 64KB (128 blocks)
# Even block from img0, odd block from img1

BLOCK_SIZE = 512
BLOCKS = 128

def read_blocks(fname):
    with open(fname, 'rb') as f:
        return [f.read(BLOCK_SIZE) for _ in range(BLOCKS)]

def write_blocks(fname, blocks):
    with open(fname, 'wb') as f:
        for blk in blocks:
            f.write(blk)

def main():
    b0 = read_blocks('img0.64k')
    b1 = read_blocks('img1.64k')
    result = []
    for i in range(BLOCKS):
        if i % 2 == 0:
            result.append(b0[i])
        else:
            result.append(b1[i])
    write_blocks('test.img', result)

if __name__ == '__main__':
    main()

