import sys
import binascii

def analyze(img0_path, img1_path, report_path):
    BLOCK = 512
    COUNT = 128
    with open(img0_path, 'rb') as f0, open(img1_path, 'rb') as f1:
        blocks0 = [f0.read(BLOCK) for _ in range(COUNT)]
        blocks1 = [f1.read(BLOCK) for _ in range(COUNT)]

    with open(report_path, 'w') as rpt:
        rpt.write('Block | Block0-start | Block1-start | Same? | XOR 0/FF/other | Block0 0/FF | Block1 0/FF | Possible inversion/parity\n')
        for i in range(COUNT):
            b0 = blocks0[i]
            b1 = blocks1[i]
            xor = bytes([a ^ b for a, b in zip(b0, b1)])
            same = (b0 == b1)
            zerob0 = set(b0) == {0x00} or set(b0) == {0xff}
            zerob1 = set(b1) == {0x00} or set(b1) == {0xff}
            xor0 = set(xor) == {0x00}
            xorff = set(xor) == {0xff}
            line = []
            line.append(f'{i:3d}   | {repr(b0[:4])} | {repr(b1[:4])} | {str(same):5s}   | ')
            if xor0:
                line.append('XOR=00; ')
            elif xorff:
                line.append('XOR=FF; ')
            if zerob0:
                line.append('block0 zero/ff or ')
            if zerob1:
                line.append('block1 zero/ff; ')
            if (xorff or xor0) and (not same):
                line.append('possible parity/inversion; ')
            rpt.write(''.join(line) + '\n')

if __name__ == '__main__':
    analyze('/tmp/img0.64k', '/tmp/img1.64k', '/tmp/pattern_report.txt')

